-- Sección «Fechas importantes» de la landing (HU-32): fechas de la familia mercedaria.
-- Agrega solo la clave fechas: conserva el resto del contenido editado.
UPDATE contenido_landing
SET contenido = JSON_SET(contenido, '$.fechas', JSON_EXTRACT('{"f":{"titulo":"Fechas importantes","descripcion":"Celebraciones y recuerdos que marcan el camino de la familia mercedaria.","tarjetas":[{"fecha":"7 de enero","titulo":"San Raimundo de Peñafort","descripcion":"Recordamos a san Raimundo de Peñafort, quien colaboró con san Pedro Nolasco en la fundación de la Orden de la Merced."},{"fecha":"28 de enero","titulo":"San Pedro Nolasco","descripcion":"Fiesta de nuestro Padre y fundador, titular de nuestra parroquia. Se celebra solemnemente, dando a conocer sus virtudes y ejemplos a los fieles."},{"fecha":"1 de agosto","titulo":"Aparición de la Virgen de la Merced","descripcion":"Según la tradición, en 1218 la Virgen María se apareció a san Pedro Nolasco y le inspiró fundar una Orden para rescatar a los cautivos."},{"fecha":"10 de agosto","titulo":"Fundación de la Orden","descripcion":"En 1218, en Barcelona, san Pedro Nolasco fundó la Orden de la Bienaventurada Virgen María de la Merced de la Redención de los Cautivos."},{"fecha":"31 de agosto","titulo":"San Ramón Nonato","descripcion":"Religioso mercedario que se entregó por la libertad de los cautivos. Es invocado como patrono de las mujeres embarazadas, las parteras y los recién nacidos."},{"fecha":"24 de septiembre","titulo":"Nuestra Señora de la Merced","descripcion":"Celebración solemne de la festividad de nuestra santísima Madre de la Merced."}]}}', '$.f'))
WHERE id = 1;
